static_assert(sizeof(l4d2_data::Resource) == sizeof(void*), "D3D resource diagnostic state is optional");
void* operator new(size_t bytes) {
  ++diagnostic_work::allocations;
  if (diagnostic_work::failAllocation) { throw std::bad_alloc(); }
  if (void* data = std::malloc(bytes ? bytes : 1)) { return data; }
  throw std::bad_alloc();
}
void operator delete(void* data) noexcept { std::free(data); }
void operator delete(void* data, size_t) noexcept { std::free(data); }
void* operator new[](size_t bytes) { return ::operator new(bytes); }
void operator delete[](void* data) noexcept { std::free(data); }
