static void learnedLoop(const char* mode) {
  using namespace l4d2_readback;
  using namespace diagnostic_work;
  configuredPolicy = "learned-aggressive";
  configuredDb = std::string(mode) + ".db";
  std::filesystem::remove(configuredDb);
  retentionDiagnostics = std::strcmp(mode, "lg-off") != 0;
  failRetentionFile = !std::strcmp(mode, "retention-log-failure");
  failRetentionWrite = !std::strcmp(mode, "retention-write-failure");
  unsigned readbacks = 0, acknowledgements = 0;
  struct Backend {
    Request request;
    Layout layout;
    std::vector<uint8_t> bytes;
    explicit Backend(const Request& r) : request(r) {
      l4d2_readback::layout(r.width, r.height, r.format, layout);
      bytes.assign(layout.bytes, 0x71);
    }
    HRESULT descriptor(D3DSURFACE_DESC& desc) {
      desc = { static_cast<D3DFORMAT>(request.format), D3DRTYPE_SURFACE, request.usage,
        static_cast<D3DPOOL>(request.pool), D3DMULTISAMPLE_NONE, 0, request.width, request.height };
      return S_OK;
    }
    HRESULT synchronize(Response& response) { response.flushRequested = response.eventWait = 1; return S_OK; }
    HRESULT lock(D3DLOCKED_RECT& locked) { locked = { static_cast<INT>(layout.rowBytes), bytes.data() }; return S_OK; }
    HRESULT unlock() { return S_OK; }
  };
  for (unsigned run = 0; run < 2; ++run) {
    l4d2_retention::Runtime runtime;
    auto& learned = runtime.context;
    assert(learned.enabled && !learned.fallback && learned.db.valid());
    if (failRetentionFile || failRetentionWrite || !retentionDiagnostics) { assert(!learned.log); }
    if (!std::strcmp(mode, "retention-callback-failure")) {
      learned.log = [](const char*) { throw std::bad_alloc(); };
    }
    learned.exchange = [&](const Request& r, Temporary& temporary, Response& response, uint64_t& elapsed) -> HRESULT {
      const auto hr = temporary.create(r); if (FAILED(hr)) { return hr; }
      Backend backend(r);
      assert(runShared(backend, r, true, true));
      assert(temporary.wait(1000) == WAIT_OBJECT_0);
      response = temporary.response(); elapsed = 0;
      if (acknowledgement(r)) { ++acknowledgements; } else { ++readbacks; }
      return response.hresult;
    };
    PagefileShadow backing;
    l4d2_residency::Context residency;
    residency.policy = l4d2_residency::Policy::LearnedAggressive;
    residency.exchange = learned.exchange;
    // A failing GC log must not replace its intrinsic results either.
    if (!std::strcmp(mode, "retention-callback-failure")) {
      residency.log = [](const char*) { throw std::bad_alloc(); };
      residency.userLog = [](const char*) { throw std::bad_alloc(); };
    }
    const D3DSURFACE_DESC desc { D3DFMT_DXT1, D3DRTYPE_SURFACE, 0, D3DPOOL_MANAGED,
      D3DMULTISAMPLE_NONE, 0, 256, 256 };
    l4d2_retention::Parent parent(learned, 1, 256, 256, 1, D3DFMT_DXT1, 0, D3DPOOL_MANAGED, "fixture:1234", true);
    l4d2_residency::Entry entry(residency, backing, 2, desc);
    entry.type = l4d2_shadow::Type::Texture2DLevel;
    parent.attach(0, 2, backing);
    entry.learnedDecision = [&] { return parent.decision(0); };
    entry.learnedRecovery = [&](uint32_t flags, const RECT& rect) { return parent.beforeLock(0, flags, rect); };
    entry.learnedEvicted = [&](uint64_t bytes) { parent.noteEvicted(0, bytes); };
    entry.learnedFailure = [&](const char* reason) { parent.reclaimFailure(reason); };
    Layout layout; assert(l4d2_readback::layout(256, 256, D3DFMT_DXT1, layout));
    auto* original = backing.acquire(layout.bytes, 0); assert(original);
    std::memset(original, 0x71, layout.bytes);
    Digest digest; assert(hashBytes(original, layout.bytes, digest) == S_OK);
    backing.release(0); entry.uploaded(layout.bytes); parent.uploaded(0, true, digest, S_OK);
    assert(!learned.fallback && !l4d2_observation::memoryMonitoring);
    assert(parent.decision(0) == (run ? l4d2_residency::LearnedDecision::Keep : l4d2_residency::LearnedDecision::Evictable));
    const auto gc = l4d2_residency::RunPageBlockGc(residency, l4d2_residency::PageBlockGcMode::Learned);
    assert(gc.pageBlocksEvicted == (run ? 0u : 1u));
    if (!run) {
      assert(backing.recoveryMissing() && !backing.backingBytes() && learned.db.records() == 0);
      assert(entry.beforeLock(D3DLOCK_READONLY, RECT { 0, 0, 256, 256 }));
      assert(!backing.recoveryMissing() && parent.decision(0) == l4d2_residency::LearnedDecision::Keep);
      auto* restored = backing.acquire(layout.bytes, 0); assert(restored);
      for (unsigned i = 0; i < layout.bytes; ++i) { assert(restored[i] == 0x71); }
      backing.release(0);
    }
    assert(learned.db.records() == 1 && !learned.fallback);
    if (runtime.file != INVALID_HANDLE_VALUE) { CloseHandle(runtime.file); }
  }
  assert(readbacks == 1 && acknowledgements == 1);
  assert(!l4d2_api_wait::state && !bridge_exception::testHistoryState());
  assert(!threads && !l4d2_memory::nextSample && !l4d2_memory::surfaceBackingBytes);
  std::printf("%s: LG DB miss/eviction/Host recovery/KEEP promotion/persisted DB hit passed; fallback=0\n", mode);
}

